const config = $input.first()?.json || {};
const sourceFolderId = String(config.sourceFolderId || '').trim();
const processedFolderId = String(config.processedFolderId || '').trim();

return $input.all().map(({ json }) => {
  const attrs = json.attributes || {};
  const fileId = json.id || json.resourceId || attrs.id || '';
  const fileName = attrs.name || json.name || json.fileName || '';
  const mimeType = attrs.mime_type || attrs.mimeType || json.mimeType || '';
  const extension = attrs.extn || (fileName.includes('.') ? fileName.split('.').pop() : '') || '';
  return {
    json: {
      source: 'workdrive',
      sourceFolderId,
      processedFolderId,
      fileId,
      fileName,
      mimeType,
      extension,
    },
  };
}).filter(({ json }) => {
  if (!json.fileId || !json.fileName) return false;
  const lowerName = json.fileName.toLowerCase();
  const lowerMime = String(json.mimeType || '').toLowerCase();
  const lowerExt = String(json.extension || '').toLowerCase();
  return lowerName.endsWith('.pdf') || lowerMime.includes('pdf') || lowerExt === 'pdf';
});

return $input.all().map(({ json }) => ({
  json: {
    ...json,
    source: String(json.source || '').trim().toLowerCase(),
    workdrive_file_id: String(json.workdrive_file_id || json.workdriveFileId || '').trim(),
    processed_folder_id: String(json.processed_folder_id || json.processedFolderId || '').trim(),
  },
})).filter(({ json }) => Boolean(json.workdrive_file_id && json.processed_folder_id));

// 1. Retrieve all active JDs and deduplicate by ID
const rawJds = $('Fetch Active JDs').all().map(item => item.json);
const jds = [];
const seenIds = new Set();
for (const j of rawJds) {
  if (j && j.id && !seenIds.has(j.id)) {
    seenIds.add(j.id);
    jds.push(j);
  }
}

// 2. Retrieve all saved Candidates
const savedCandidates = $('Save Candidate — PostgreSQL').all().map(item => item.json);

// 3. Retrieve all parsed candidates from Normalize Skills
const candidates = $('Normalize Skills').all().map(item => item.json);

return candidates.map((c, idx) => {
  const savedC = savedCandidates.find(sc => sc.email === c.email) || savedCandidates[idx] || {};

  const jdSections = jds.map((j, jdIdx) => `--- JOB DESCRIPTION #${jdIdx + 1} ---
- jd_id: ${j.id}
- Title: ${j.title}
- Department: ${j.department || 'N/A'}
- Required Skills: ${Array.isArray(j.required_skills) ? j.required_skills.join(', ') : JSON.stringify(j.required_skills || 'None')}
- Preferred Skills: ${Array.isArray(j.preferred_skills) ? j.preferred_skills.join(', ') : JSON.stringify(j.preferred_skills || 'None')}
- Experience Required: ${j.experience_min || 0} - ${j.experience_max || 0} years
- Education Required: ${j.education || 'N/A'}
- AI Evaluation Guidelines: ${j.ai_prompt || 'None'}`).join('\n\n');

  const prompt = `# HireFlow Enterprise AI Candidate Evaluation Prompt

You are a **Senior Technical Recruiter and Hiring Manager at Virim Infotech** with extensive experience screening software engineers.

Your responsibility is to evaluate a candidate **ONLY against the supplied Job Description (JD).**

Do NOT assume skills that are not explicitly mentioned in the resume.

Use only the evidence available in:
* Candidate Resume
* Candidate Skills
* Candidate Experience
* Candidate Projects
* Candidate Education
* Job Description

---

# Evaluation Rules

Follow these principles strictly.

## Rule 1
Treat the Job Description as the source of truth.
Every score must be based on how well the candidate matches that specific Job Description.

## Rule 2
Only use evidence found in the resume.
Never assume hidden experience, hidden skills, or hidden projects. If something is not mentioned, treat it as unavailable.

## Rule 3
Be lenient but fair. Mark candidate scores based on the detailed grading criteria below.

---

# Scoring Breakdown (Sum to 100 overall score)

## 1. Technical Score (0-60 points)
- Evaluate coverage of mandatory and preferred skills listed in the JD.
- If the candidate covers all technical skills mentioned in the JD, reward a full score of **60 out of 60**. 
- Reduce the score proportionally for missing skills.

## 2. Experience Score (0-10 points)
- If the candidate matches the experience requirements (years of experience), mark **10 out of 10**.
- **Fresher Internship Rule**: If the candidate is a fresher (0 years of experience) but has completed internships, mark **10 out of 10**.
- If the candidate is a fresher (0 years of experience) and has NOT done any internship, mark **5 out of 10**.

## 3. Project Score (0-10 points)
- Evaluate projects based on whether they use the skills listed in the JD.
- The projects must be somewhat innovative and functional (not just extremely basic tutorials).
- Rate the projects out of **10**.

## 4. Education & Certification Score (0-15 points)
This score combines academic matches and certification alignments:
- **Academic matching (0-5 points)**: If the candidate's degree/college education matches the JD criteria, reward **5 points**. For non-matching or other degrees, be lenient and award a minimum of **2 points**.
- **Certifications (0-10 points)**: If the candidate has certifications matching or highly relevant to the JD skills, award **10 points**. If they have some certifications but they are not fully aligned, award **5 points**. If they have no certifications, award **0 points**.

## 5. Communication Score (0-5 points)
- Evaluate resume presentation, clarity of layout, and use of proper English.
- If the resume is professionally written in proper English, award up to **5 points**. 
- Award a minimum of **2 points** as a baseline for legible English.

---

# Overall Score
Overall Score = Technical Score + Experience Score + Project Score + Education & Certification Score + Communication Score. (Must be an integer sum from 0 to 100).

---

# Inputs

## Active Job Descriptions
${jdSections}

---

## Candidate Profile
Name: ${c.candidate_name || 'Unknown'}
Experience: ${c.years_of_exp || 0} years
Education: ${c.degree || 'N/A'}
Specialization: ${c.specialization || 'N/A'}
College: ${c.college || 'N/A'}
Frontend Skills: ${c.frontend_skills || 'None'}
Backend Skills: ${c.backend_skills || 'None'}
Database Skills: ${c.database_skills || 'None'}
AI Skills: ${c.ai_ml_skills || 'None'}
Cloud Skills: ${c.cloud_devops || 'None'}
Programming Languages: ${c.programming_langs || 'None'}
Projects: ${c.notable_projects || 'None'}
Certifications: ${c.certifications || 'None'}

Resume Text:
${c.resume_text || ''}

---

# Required Output
Return ONLY a valid JSON Array.
Do NOT include markdown block markers (such as triple backticks followed by 'json') in the response.
Return exactly this structure containing one object for each of the JDs listed above:
[
  {
    "jd_id": <jd_id from corresponding Job Description>,
    "jd_title": "<Title from corresponding Job Description>",
    "overallScore": 0,
    "technicalScore": 0,
    "experienceScore": 0,
    "educationScore": 0, // This should hold the Education & Certification Score (0-15)
    "communicationScore": 0,
    "projectScore": 0,
    "grade": "A|B|C|D|F",
    "recommendation": "Strong Hire|Hire|Consider|Reject",
    "matchedSkills": [],
    "missingSkills": [],
    "strengths": [],
    "weaknesses": [],
    "summary": "",
    "reasoning": {
      "technical": "",
      "experience": "",
      "education": "",
      "communication": "",
      "projects": ""
    }
  }
]`;

  return {
    json: {
      candidate_id: savedC.id,
      aiPrompt: prompt
    }
  };
});

const items = $input.all();
const promptItems = $('Build Context & Prompt').all();
const activeJds = $('Fetch Active JDs').all().map(item => item.json);
const validJdIds = activeJds.map(j => Number(j.id));
const allMatches = [];

for (let idx = 0; idx < items.length; idx++) {
  const item = items[idx];
  const promptItem = promptItems[idx] || {};
  const candidateId = Number(promptItem.json?.candidate_id || 1);

  const d = item.json || {};
  const rawResponse = d.text || d.output || d.response?.text || (d.choices || [])[0]?.message?.content;

  let parsedList = [];
  if (rawResponse) {
    try {
      const cleaned = String(rawResponse)
        .replace(/\`\`\`json\s*/gi, '')
        .replace(/\`\`\`\s*/g, '')
        .replace(/^[^{\[]*/, '')
        .replace(/[^}\]]*$/, '');
      parsedList = JSON.parse(cleaned);
    } catch (e) {
      parsedList = [];
    }
  }

  if (!Array.isArray(parsedList)) {
    parsedList = [parsedList];
  }

  const getVal = (obj, keys, defaultValue) => {
    for (const key of keys) {
      if (obj[key] !== undefined) return obj[key];
      const foundKey = Object.keys(obj).find(k => k.toLowerCase() === key.toLowerCase());
      if (foundKey) return obj[foundKey];
    }
    return defaultValue;
  };

  const getArrayVal = (obj, keys) => {
    const val = getVal(obj, keys, []);
    if (Array.isArray(val)) return val;
    if (typeof val === 'string') {
      return val.split(',').map(s => s.trim()).filter(Boolean);
    }
    return [];
  };

  let evalIdx = 0;
  for (const evalObj of parsedList) {
    let jd_id = Number(getVal(evalObj, ['jd_id', 'jdId'], 0));
    if (!validJdIds.includes(jd_id)) {
      const returnedTitle = String(getVal(evalObj, ['jd_title', 'jdTitle', 'title'], '')).toLowerCase().trim();
      const matchedJdByTitle = activeJds.find(j => 
        j.title && (returnedTitle.includes(j.title.toLowerCase().trim()) || 
        j.title.toLowerCase().trim().includes(returnedTitle))
      );
      if (matchedJdByTitle) {
        jd_id = Number(matchedJdByTitle.id);
      } else if (evalIdx < activeJds.length) {
        jd_id = Number(activeJds[evalIdx].id);
      } else {
        jd_id = validJdIds[0] || 1;
      }
    }
    evalIdx++;

    const overall_score = Number(getVal(evalObj, ['overallScore', 'overall_score'], 0));
    const technical_score = Number(getVal(evalObj, ['technicalScore', 'technical_score'], 0));
    const experience_score = Number(getVal(evalObj, ['experienceScore', 'experience_score'], 0));
    const education_score = Number(getVal(evalObj, ['educationScore', 'education_score'], 0));
    const communication_score = Number(getVal(evalObj, ['communicationScore', 'communication_score'], 0));
    const project_score = Number(getVal(evalObj, ['projectScore', 'project_score'], 0));

    const recommendation = String(getVal(evalObj, ['recommendation'], 'Consider'));
    const grade = String(getVal(evalObj, ['grade'], 'B'));

    const matched_skills = getArrayVal(evalObj, ['matchedSkills', 'matched_skills']);
    const missing_skills = getArrayVal(evalObj, ['missingSkills', 'missing_skills']);
    const strengths = getArrayVal(evalObj, ['strengths']);
    const weaknesses = getArrayVal(evalObj, ['weaknesses']);

    const reasoning = evalObj.reasoning || {};
    const explanation = String(getVal(evalObj, ['summary'], '')) || 
      `Tech Alignment: ${reasoning.technical || 'N/A'}. Experience Alignment: ${reasoning.experience || 'N/A'}.`;

    allMatches.push({
      json: {
        candidate_id: candidateId,
        jd_id,
        overall_score,
        technical_score,
        experience_score,
        education_score,
        communication_score,
        project_score,
        recommendation,
        grade,
        matched_skills: JSON.stringify(matched_skills),
        missing_skills: JSON.stringify(missing_skills),
        strengths,
        weaknesses,
        summary: explanation,
        status: 'Completed',
        scored_at: new Date().toISOString()
      }
    });
  }
}

return allMatches;
